-- Aprenda se Divertindo · 119 · Trilha Policial · lote extra 19 (100 questões de todos os níveis)
-- Rode depois do 118-trilha-policial-troca-faceis.sql. Cole tudo no SQL Editor e clique em Run. Rodar de novo apenas atualiza.
-- Números 10947 a 11046: 20 de cada nível (0 a 4), quase todas em forma de caso prático, conferidas contra o banco e o Simulado Desafio.

insert into public.questoes (id, materia, nivel, enunciado, opcoes, explicacao)
select id, materia, nivel, enunciado, opcoes, explicacao
from jsonb_to_recordset($q$[{"id": 10947, "materia": "pen", "nivel": 0, "enunciado": "Numa briga de bar, Nelson deu um soco em Jair, que ficou com um pequeno hematoma. O crime é:", "opcoes": ["Lesão corporal leve", "Tentativa de homicídio", "Lesão gravíssima", "Dano"], "explicacao": "Art. 129, caput, do CP: ofensa à integridade corporal sem resultado grave."}, {"id": 10948, "materia": "pen", "nivel": 0, "enunciado": "Paulo riscou e amassou, de propósito, o carro do vizinho. O crime é:", "opcoes": ["Dano", "Furto", "Roubo", "Receptação"], "explicacao": "Art. 163 do CP: destruir, inutilizar ou deteriorar coisa alheia."}, {"id": 10949, "materia": "pen", "nivel": 0, "enunciado": "Rita anunciou um celular, recebeu o Pix do comprador e nunca entregou nada. O crime é:", "opcoes": ["Estelionato", "Furto", "Roubo", "Dano"], "explicacao": "Art. 171 do CP: obter vantagem ilícita induzindo a vítima em erro."}, {"id": 10950, "materia": "pen", "nivel": 1, "enunciado": "Distraída com o celular, uma motorista atropelou e matou um pedestre, sem intenção. O crime é homicídio:", "opcoes": ["Culposo na direção de veículo", "Doloso qualificado pelo meio cruel", "Privilegiado", "Preterdoloso"], "explicacao": "Art. 302 do CTB."}, {"id": 10951, "materia": "pen", "nivel": 1, "enunciado": "Tiago entrou numa casa vazia pulando o muro e subindo pela janela, e levou a TV. O furto é qualificado pela:", "opcoes": ["Escalada", "Fraude", "Destreza", "Chave falsa"], "explicacao": "Art. 155, § 4º, II, do CP: escalada é o uso de via anormal para entrar."}, {"id": 10952, "materia": "pen", "nivel": 1, "enunciado": "Uma babá furtou joias da patroa, aproveitando a confiança que tinha na casa. O furto é qualificado pelo:", "opcoes": ["Abuso de confiança", "Rompimento de obstáculo", "Emprego de chave falsa", "Concurso de pessoas"], "explicacao": "Art. 155, § 4º, II, do CP."}, {"id": 10953, "materia": "pen", "nivel": 2, "enunciado": "Para roubar o carro, Ivo manteve o motorista preso dentro do veículo por horas. Isso:", "opcoes": ["Aumenta a pena do roubo", "Transforma o crime em furto", "Diminui a pena do roubo", "Não altera nada"], "explicacao": "Art. 157, § 2º, V, do CP: restrição da liberdade da vítima aumenta a pena de 1/3 até a metade."}, {"id": 10954, "materia": "pen", "nivel": 2, "enunciado": "Gabi recebeu por engano um Pix de R$ 2.000 de um desconhecido e decidiu ficar com o dinheiro. Ela comete:", "opcoes": ["Apropriação de coisa havida por erro", "Estelionato", "Furto mediante fraude por meio eletrônico", "Nenhum crime"], "explicacao": "Art. 169 do CP."}, {"id": 10955, "materia": "pen", "nivel": 2, "enunciado": "No sequestro, o crime continua se consumando durante todo o tempo do cativeiro. Por isso, ele é crime:", "opcoes": ["Permanente", "Instantâneo", "Habitual", "Unissubsistente"], "explicacao": "No crime permanente, a consumação se prolonga no tempo, e o flagrante é possível enquanto durar."}, {"id": 10956, "materia": "pen", "nivel": 3, "enunciado": "Max atirou para matar Nilo, mas errou a mira e matou Otto, que estava ao lado. Max responde:", "opcoes": ["Como se tivesse matado Nilo", "Só por homicídio culposo de Otto", "Por tentativa contra Nilo apenas", "Por nenhum crime, pelo erro"], "explicacao": "Erro na execução (art. 73 do CP): consideram-se as condições da vítima visada."}, {"id": 10957, "materia": "pen", "nivel": 3, "enunciado": "Querendo quebrar uma vitrine com uma pedra, Saulo errou e feriu um pedestre. Se o fato é previsto como culposo, ele responde por:", "opcoes": ["Lesão corporal culposa", "Dano consumado doloso", "Lesão corporal dolosa", "Tentativa de homicídio"], "explicacao": "Resultado diverso do pretendido (art. 74 do CP): responde por culpa se o fato for previsto como culposo."}, {"id": 10958, "materia": "pen", "nivel": 3, "enunciado": "Um fiscal exigiu propina de um comerciante, que se recusou a pagar. A concussão:", "opcoes": ["Já se consumou com a exigência", "Ficou apenas tentada", "Não existiu, porque não houve pagamento", "Virou corrupção ativa"], "explicacao": "A concussão é crime formal: consuma-se com a exigência, e o recebimento é exaurimento."}, {"id": 10959, "materia": "pen", "nivel": 4, "enunciado": "Para o STF, a aplicação do princípio da insignificância exige, entre outros vetores:", "opcoes": ["Mínima ofensividade e inexpressividade da lesão jurídica", "Que o agente seja primário e confesse espontaneamente o crime", "Que o valor do bem não passe de um salário mínimo", "Que a vítima concorde expressamente com o perdão"], "explicacao": "STF, HC 84.412: mínima ofensividade, nenhuma periculosidade social, reduzido grau de reprovabilidade e inexpressividade da lesão."}, {"id": 10960, "materia": "pen", "nivel": 4, "enunciado": "Pedro, reincidente, foi condenado a 4 anos de reclusão, com circunstâncias judiciais favoráveis. Pela Súmula 269 do STJ, o regime inicial pode ser:", "opcoes": ["Semiaberto", "Aberto, obrigatoriamente", "Fechado, obrigatoriamente", "Domiciliar"], "explicacao": "Súmula 269 do STJ: semiaberto ao reincidente com pena de até 4 anos, se favoráveis as circunstâncias judiciais."}, {"id": 10961, "materia": "ppen", "nivel": 0, "enunciado": "A queixa-crime é a peça que dá início à ação penal:", "opcoes": ["Privada", "Pública incondicionada", "Pública condicionada", "Militar"], "explicacao": "A ação pública começa com a denúncia do MP."}, {"id": 10962, "materia": "ppen", "nivel": 0, "enunciado": "A denúncia, oferecida pelo Ministério Público, dá início à ação penal:", "opcoes": ["Pública", "Privada", "Subsidiária", "Civil"], "explicacao": "Arts. 24 e 41 do CPP."}, {"id": 10963, "materia": "ppen", "nivel": 0, "enunciado": "No processo, a pessoa que viu o crime e é chamada para contar o que sabe é a:", "opcoes": ["Testemunha", "Perita", "Querelada", "Ré"], "explicacao": "A testemunha presta compromisso de dizer a verdade (art. 203 do CPP)."}, {"id": 10964, "materia": "ppen", "nivel": 1, "enunciado": "Um prefeito baiano foi acusado de crime comum. Em regra, quem o julga é o:", "opcoes": ["Tribunal de Justiça", "Juiz de primeira instância", "Supremo Tribunal Federal", "Tribunal do Júri"], "explicacao": "Art. 29, X, da Constituição."}, {"id": 10965, "materia": "ppen", "nivel": 1, "enunciado": "Em regra, o processo criminal corre no lugar onde o crime:", "opcoes": ["Se consumou", "Foi planejado", "Foi noticiado", "Foi esquecido"], "explicacao": "Art. 70 do CPP."}, {"id": 10966, "materia": "ppen", "nivel": 1, "enunciado": "Quando não se sabe onde o crime aconteceu, a competência é definida pelo:", "opcoes": ["Domicílio do réu", "Domicílio do juiz", "Local da delegacia", "Local do julgamento"], "explicacao": "Art. 72 do CPP."}, {"id": 10967, "materia": "ppen", "nivel": 4, "enunciado": "Preso em flagrante, Leandro não informou nenhum advogado. Nesse caso, uma cópia do auto de prisão deve ir para a:", "opcoes": ["Defensoria Pública", "Ordem dos Advogados", "Imprensa local", "Família da vítima"], "explicacao": "Art. 306, § 1º, do CPP."}, {"id": 10968, "materia": "ppen", "nivel": 4, "enunciado": "Ao receber o auto de prisão em flagrante, o juiz pode:", "opcoes": ["Relaxá-la, convertê-la em preventiva ou conceder liberdade provisória", "Apenas manter o preso até o julgamento final, sem analisar a legalidade", "Somente arquivar o caso e soltar o preso", "Condenar o preso imediatamente"], "explicacao": "Art. 310 do CPP."}, {"id": 10969, "materia": "ppen", "nivel": 2, "enunciado": "Em vez de prender, o juiz mandou o investigado usar tornozeleira. Essa medida cautelar é a:", "opcoes": ["Monitoração eletrônica", "Prisão temporária", "Fiança", "Pronúncia"], "explicacao": "Art. 319, IX, do CPP."}, {"id": 10970, "materia": "ppen", "nivel": 3, "enunciado": "O inquérito foi arquivado por falta de provas. A polícia pode voltar a investigar se:", "opcoes": ["Surgirem novas provas", "O réu pedir", "Passarem 10 anos do arquivamento", "O STF mandar"], "explicacao": "Art. 18 do CPP e Súmula 524 do STF."}, {"id": 10971, "materia": "ppen", "nivel": 3, "enunciado": "A ação penal depende de requisição do Ministro da Justiça, por exemplo, no crime contra a honra do:", "opcoes": ["Presidente da República", "Prefeito", "Vereador", "Delegado"], "explicacao": "Art. 145, parágrafo único, do CP."}, {"id": 10972, "materia": "ppen", "nivel": 4, "enunciado": "Contra a decisão que rejeita a denúncia, no processo comum do CPP, cabe:", "opcoes": ["Recurso em sentido estrito", "Apelação", "Embargos infringentes e de nulidade", "Revisão criminal"], "explicacao": "Art. 581, I, do CPP. No Juizado Especial, cabe apelação (art. 82 da Lei 9.099/1995)."}, {"id": 10973, "materia": "ppen", "nivel": 4, "enunciado": "No júri, contra a sentença de absolvição sumária (art. 415 do CPP), cabe:", "opcoes": ["Apelação", "Recurso em sentido estrito", "Embargos de declaração", "Habeas corpus"], "explicacao": "Art. 416 do CPP: contra a impronúncia ou a absolvição sumária cabe apelação."}, {"id": 10974, "materia": "const", "nivel": 0, "enunciado": "Pela Constituição, a Bahia é:", "opcoes": ["Um estado da Federação", "Um país independente", "Um território federal", "Um município"], "explicacao": "Art. 1º e art. 18 da Constituição."}, {"id": 10975, "materia": "const", "nivel": 0, "enunciado": "Léo aprendeu na escola que quem aprova as leis federais é o:", "opcoes": ["Congresso Nacional", "Supremo Tribunal Federal", "Ministério Público", "Tribunal de Contas"], "explicacao": "O Congresso é formado pela Câmara dos Deputados e pelo Senado (art. 44)."}, {"id": 10976, "materia": "const", "nivel": 2, "enunciado": "Na linha de sucessão do Presidente da República, depois do Vice-Presidente, vem o:", "opcoes": ["Presidente da Câmara dos Deputados", "Presidente do Senado Federal", "Presidente do STF", "Ministro da Justiça"], "explicacao": "Art. 80 da Constituição: Câmara, Senado e STF, nessa ordem."}, {"id": 10977, "materia": "const", "nivel": 2, "enunciado": "No Congresso Nacional, os senadores representam:", "opcoes": ["Os Estados e o Distrito Federal", "O povo, proporcionalmente", "Os municípios", "Os partidos políticos"], "explicacao": "Art. 46 da Constituição. Os deputados representam o povo (art. 45)."}, {"id": 10978, "materia": "const", "nivel": 2, "enunciado": "Pela Constituição, a locomoção pelo território nacional é livre em tempo de:", "opcoes": ["Paz", "Guerra", "Eleição", "Estado de sítio"], "explicacao": "Art. 5º, XV, da Constituição."}, {"id": 10979, "materia": "const", "nivel": 1, "enunciado": "Ninguém pode perder a liberdade ou seus bens sem o devido:", "opcoes": ["Processo legal", "Aviso por telefone", "Pagamento de taxa", "Aval do prefeito"], "explicacao": "Art. 5º, LIV, da Constituição."}, {"id": 10980, "materia": "const", "nivel": 3, "enunciado": "Para ser aprovada, uma emenda à Constituição precisa passar em cada Casa do Congresso em:", "opcoes": ["Dois turnos, com 3/5 dos votos", "Um turno, por maioria simples", "Dois turnos, por maioria absoluta", "Um turno, com 2/3 dos votos"], "explicacao": "Art. 60, § 2º, da Constituição."}, {"id": 10981, "materia": "const", "nivel": 3, "enunciado": "Não pode ser objeto de emenda que tente abolir (cláusula pétrea):", "opcoes": ["O voto direto, secreto, universal e periódico", "A quantidade de ministérios do governo federal", "O número de deputados por estado", "O salário mínimo nacional"], "explicacao": "Art. 60, § 4º, da Constituição."}, {"id": 10982, "materia": "const", "nivel": 4, "enunciado": "O estado de defesa é decretado pelo Presidente, ouvidos os Conselhos da República e de Defesa Nacional, por até:", "opcoes": ["30 dias, prorrogável uma vez", "60 dias, sem prorrogação", "90 dias, prorrogável duas vezes", "15 dias, sem prorrogação"], "explicacao": "Art. 136, § 2º, da Constituição."}, {"id": 10983, "materia": "const", "nivel": 4, "enunciado": "No estado de defesa, a prisão por crime contra o Estado, determinada pelo executor da medida, não pode durar mais de:", "opcoes": ["10 dias, salvo autorização judicial", "30 dias, sem nenhum controle judicial", "48 horas, sem prorrogação", "60 dias, a critério do executor"], "explicacao": "Art. 136, § 3º, III, da Constituição."}, {"id": 10984, "materia": "adm", "nivel": 0, "enunciado": "Um chefe quis cobrar uma taxa que nenhuma lei criou. Isso fere o princípio da:", "opcoes": ["Legalidade", "Eficiência", "Publicidade", "Continuidade"], "explicacao": "Na Administração Pública, só se faz o que a lei permite."}, {"id": 10985, "materia": "adm", "nivel": 0, "enunciado": "Publicar no Diário Oficial a nomeação de um servidor atende ao princípio da:", "opcoes": ["Publicidade", "Legalidade", "Impessoalidade", "Eficiência"], "explicacao": "Art. 37 da Constituição."}, {"id": 10986, "materia": "adm", "nivel": 1, "enunciado": "Bens públicos, como as viaturas da polícia, são:", "opcoes": ["Impenhoráveis", "Penhoráveis", "Usucapíveis", "Vendáveis livremente"], "explicacao": "Bens públicos não podem ser penhorados nem adquiridos por usucapião (art. 102 do Código Civil)."}, {"id": 10987, "materia": "adm", "nivel": 1, "enunciado": "Um terreno público sem nenhuma destinação, que pode até ser vendido na forma da lei, é um bem:", "opcoes": ["Dominical", "De uso comum do povo", "De uso especial", "Particular"], "explicacao": "Art. 99, III, do Código Civil."}, {"id": 10988, "materia": "adm", "nivel": 2, "enunciado": "A prefeitura quer leiloar um galpão abandonado que não serve a nenhum serviço público. Isso é possível porque o galpão é um bem:", "opcoes": ["Dominical", "De uso especial", "De uso comum do povo", "Inalienável"], "explicacao": "Art. 101 do Código Civil: os bens dominicais podem ser alienados, observadas as exigências da lei."}, {"id": 10989, "materia": "adm", "nivel": 2, "enunciado": "No ato administrativo, o motivo é:", "opcoes": ["A situação de fato e de direito que justifica o ato", "O servidor que assina o ato", "O resultado prático que o ato produz", "O papel em que o ato é publicado"], "explicacao": "Os elementos do ato são competência, finalidade, forma, motivo e objeto."}, {"id": 10990, "materia": "adm", "nivel": 3, "enunciado": "Pela teoria dos motivos determinantes, se o motivo declarado no ato for falso, o ato:", "opcoes": ["É inválido", "Continua válido", "Vira discricionário", "Só pode ser revogado"], "explicacao": "O motivo declarado vincula a Administração, mesmo quando não era obrigatório declarar."}, {"id": 10991, "materia": "adm", "nivel": 3, "enunciado": "A concessão de serviço público (Lei 8.987/1995) é precedida de licitação na modalidade:", "opcoes": ["Concorrência ou diálogo competitivo", "Pregão ou leilão, conforme o valor do contrato", "Convite ou tomada de preços", "Concurso"], "explicacao": "Art. 2º, II, da Lei 8.987/1995, com a redação da Lei 14.133/2021."}, {"id": 10992, "materia": "adm", "nivel": 4, "enunciado": "Segundo o STF, a nomeação do cônjuge do governador para secretário de estado, cargo de natureza política:", "opcoes": ["Em regra não é nepotismo, salvo fraude ou falta de qualificação", "É sempre nepotismo, proibido pela Súmula Vinculante 13 em qualquer caso", "Só é permitida se o cônjuge for servidor efetivo", "Depende de autorização da Assembleia Legislativa"], "explicacao": "O STF entende que a SV 13 não alcança, em regra, cargos políticos (Rcl 6.650)."}, {"id": 10993, "materia": "leg", "nivel": 0, "enunciado": "Kátia foi agredida pelo ex-namorado, com quem nunca morou. A Lei Maria da Penha se aplica?", "opcoes": ["Sim", "Não, só para casadas", "Não, só se morassem juntos", "Só se ainda namorassem"], "explicacao": "Art. 5º, III, da Lei 11.340/2006: relação íntima de afeto, independentemente de coabitação. Súmula 600 do STJ."}, {"id": 10994, "materia": "leg", "nivel": 0, "enunciado": "Seu Zé tem 61 anos. Pelo Estatuto da Pessoa Idosa, ele é idoso?", "opcoes": ["Sim, a partir dos 60 anos", "Não, só a partir dos 65", "Não, só a partir dos 70", "Só se for aposentado"], "explicacao": "Art. 1º da Lei 10.741/2003."}, {"id": 10995, "materia": "leg", "nivel": 0, "enunciado": "Numa blitz, o bafômetro mostrou 0,3 mg de álcool por litro de ar no motorista. Pelo CTB, isso é:", "opcoes": ["Crime", "Só advertência", "Conduta permitida", "Contravenção"], "explicacao": "Art. 306, § 1º, I, do CTB."}, {"id": 10996, "materia": "leg", "nivel": 1, "enunciado": "Comemorando o aniversário, Gil deu tiros para o alto na rua. Pelo Estatuto do Desarmamento, ele comete:", "opcoes": ["Disparo de arma de fogo", "Posse irregular de arma", "Omissão de cautela", "Comércio ilegal"], "explicacao": "Art. 15 da Lei 10.826/2003."}, {"id": 10997, "materia": "leg", "nivel": 1, "enunciado": "Por ciúmes, Lúcio matou a esposa dentro de casa, num histórico de agressões. O crime é:", "opcoes": ["Feminicídio", "Homicídio privilegiado", "Lesão seguida de morte", "Homicídio culposo"], "explicacao": "Art. 121-A do CP (Lei 14.994/2024): morte de mulher no contexto de violência doméstica e familiar."}, {"id": 10998, "materia": "leg", "nivel": 1, "enunciado": "Lucas, de 15 anos, praticou um ato infracional leve. Pelo ECA, a medida mais branda, uma repreensão verbal do juiz, é a:", "opcoes": ["Advertência", "Internação", "Semiliberdade", "Liberdade assistida"], "explicacao": "Art. 115 do ECA."}, {"id": 10999, "materia": "leg", "nivel": 2, "enunciado": "Depois da Lei 14.994/2024, a pena do feminicídio é de:", "opcoes": ["Reclusão de 20 a 40 anos", "Reclusão de 12 a 30 anos", "Reclusão de 6 a 20 anos", "Detenção de 1 a 3 anos"], "explicacao": "Art. 121-A do CP."}, {"id": 11000, "materia": "leg", "nivel": 4, "enunciado": "Na Lei de Drogas, quem financia ou custeia o tráfico (art. 36) fica sujeito a:", "opcoes": ["Reclusão de 8 a 20 anos", "Reclusão de 5 a 15 anos", "Detenção de 6 meses a 1 ano", "Reclusão de 2 a 6 anos"], "explicacao": "Art. 36 da Lei 11.343/2006."}, {"id": 11001, "materia": "leg", "nivel": 4, "enunciado": "Na Lei de Tortura, quem se omite quando tinha o dever de evitar ou apurar a tortura é punido com:", "opcoes": ["Detenção de 1 a 4 anos", "Reclusão de 8 a 16 anos", "Multa apenas", "A mesma pena de quem torturou"], "explicacao": "Art. 1º, § 2º, da Lei 9.455/1997."}, {"id": 11002, "materia": "leg", "nivel": 3, "enunciado": "Pela Lei 13.869/2019, constranger um preso, com violência, a exibir o corpo à curiosidade do público é:", "opcoes": ["Abuso de autoridade", "Exercício regular de direito", "Mera falta disciplinar", "Conduta permitida"], "explicacao": "Art. 13, I, da Lei 13.869/2019."}, {"id": 11003, "materia": "leg", "nivel": 3, "enunciado": "Condenado por ameaçar a esposa, Paulo pediu para cumprir a pena doando uma cesta básica. Pela Lei Maria da Penha:", "opcoes": ["Isso é proibido", "Isso é permitido", "Só se ele for primário", "Só se a vítima aceitar"], "explicacao": "Art. 17 da Lei 11.340/2006 veda pena de cesta básica, prestação pecuniária ou multa isolada."}, {"id": 11004, "materia": "leg", "nivel": 3, "enunciado": "Kevin, de 16 anos, cumpre internação há 6 meses. Pelo ECA, a medida dele:", "opcoes": ["Deve ser reavaliada agora", "Só será revista após 3 anos", "Nunca pode ser revista", "Acaba automaticamente hoje"], "explicacao": "Art. 121, § 2º, do ECA: reavaliação no máximo a cada 6 meses."}, {"id": 11005, "materia": "leg", "nivel": 4, "enunciado": "Na Lei 12.850/2013, a pena da organização criminosa aumenta até a metade se houver:", "opcoes": ["Emprego de arma de fogo", "Apenas quatro integrantes", "Atuação em um só bairro", "Confissão dos integrantes"], "explicacao": "Art. 2º, § 2º, da Lei 12.850/2013."}, {"id": 11006, "materia": "leg", "nivel": 2, "enunciado": "Na Lei de Drogas, quem colabora voluntariamente na identificação dos demais e na recuperação do produto do crime tem a pena reduzida de:", "opcoes": ["1/3 a 2/3", "1/6 a 1/3", "Metade sempre", "1/5 a 1/2"], "explicacao": "Art. 41 da Lei 11.343/2006."}, {"id": 11007, "materia": "port", "nivel": 0, "enunciado": "Complete: \"O suspeito ____ preso ontem à noite.\"", "opcoes": ["foi", "fui", "foram", "fomos"], "explicacao": "Sujeito singular e fato passado: \"foi\"."}, {"id": 11008, "materia": "port", "nivel": 0, "enunciado": "Assinale a palavra escrita corretamente:", "opcoes": ["ocorrência", "ocorência", "ocorrênsia", "ocorrencía"], "explicacao": "A grafia correta é \"ocorrência\"."}, {"id": 11009, "materia": "port", "nivel": 1, "enunciado": "O antônimo de \"absolvição\" é:", "opcoes": ["condenação", "perdão", "liberação", "inocência"], "explicacao": "Absolver é o contrário de condenar."}, {"id": 11010, "materia": "port", "nivel": 1, "enunciado": "Em \"A testemunha mentiu ao delegado\", o verbo está no:", "opcoes": ["Pretérito perfeito", "Presente", "Futuro do presente", "Imperativo"], "explicacao": "Mentiu indica ação concluída no passado."}, {"id": 11011, "materia": "port", "nivel": 2, "enunciado": "Complete: \"O suspeito era um ____ motorista.\"", "opcoes": ["mau", "mal", "máu", "maus"], "explicacao": "\"Mau\" é adjetivo (oposto de bom); \"mal\" é advérbio (oposto de bem)."}, {"id": 11012, "materia": "port", "nivel": 2, "enunciado": "Complete: \"O delegado não explicou ____ arquivou o caso.\"", "opcoes": ["por que", "porque", "por quê", "porquê"], "explicacao": "\"Por que\" separado e sem acento: equivale a \"o motivo pelo qual\"."}, {"id": 11013, "materia": "port", "nivel": 3, "enunciado": "Complete: \"Os policiais chegaram ___ uma hora e sairão daqui ___ duas horas.\"", "opcoes": ["há / a", "a / há", "há / há", "a / a"], "explicacao": "\"Há\" para tempo passado; \"a\" para tempo futuro."}, {"id": 11014, "materia": "port", "nivel": 3, "enunciado": "Na norma-padrão, complete: \"O investigador prefere café ____ chá.\"", "opcoes": ["a", "do que", "que", "mais que"], "explicacao": "Preferir uma coisa a outra."}, {"id": 11015, "materia": "port", "nivel": 4, "enunciado": "A forma passiva analítica de \"A perícia analisou as provas\" é:", "opcoes": ["As provas foram analisadas pela perícia.", "As provas analisaram-se pela perícia.", "A perícia foi analisada pelas provas.", "Analisaram as provas da perícia."], "explicacao": "O objeto direto vira sujeito, com ser + particípio e agente da passiva."}, {"id": 11016, "materia": "port", "nivel": 4, "enunciado": "Assinale a frase em que a vírgula está empregada corretamente:", "opcoes": ["Salvador, capital da Bahia, recebeu a operação.", "Os policiais, prenderam o suspeito na feira de São Joaquim.", "O laudo foi entregue, ao delegado ontem.", "Ele disse, que voltaria para depor."], "explicacao": "O aposto explicativo vem entre vírgulas. Não se separa o sujeito do verbo, o verbo do complemento, nem a oração da integrante."}, {"id": 11017, "materia": "inf", "nivel": 0, "enunciado": "Para abrir uma página da internet, como o site do jogo, usa-se um:", "opcoes": ["Navegador", "Antivírus", "Editor de planilhas", "Leitor de PDF"], "explicacao": "Chrome, Edge, Firefox e Safari são navegadores."}, {"id": 11018, "materia": "inf", "nivel": 1, "enunciado": "Uma senha forte é aquela que:", "opcoes": ["Mistura letras, números e símbolos", "Usa a data de aniversário", "Repete o próprio nome", "Tem só quatro números"], "explicacao": "Senhas longas e variadas são mais difíceis de adivinhar."}, {"id": 11019, "materia": "inf", "nivel": 2, "enunciado": "A autenticação em dois fatores consiste em:", "opcoes": ["Exigir algo além da senha, como um código no celular", "Usar duas senhas iguais em sites diferentes ao mesmo tempo", "Trocar a senha a cada dois dias", "Desligar o antivírus para entrar mais rápido"], "explicacao": "Mesmo que a senha vaze, o invasor precisa do segundo fator."}, {"id": 11020, "materia": "inf", "nivel": 2, "enunciado": "O malware que criptografa os arquivos da vítima e pede resgate para liberá-los é o:", "opcoes": ["Ransomware", "Adware", "Spyware", "Worm"], "explicacao": "Ransomware vem de ransom, resgate em inglês."}, {"id": 11021, "materia": "inf", "nivel": 3, "enunciado": "No Excel, a célula C1 tem =A1+B1. Ao copiá-la para C2, a fórmula fica:", "opcoes": ["=A2+B2", "=A1+B1", "=B1+C1", "=A1+B2"], "explicacao": "Referências relativas acompanham o deslocamento da célula."}, {"id": 11022, "materia": "inf", "nivel": 4, "enunciado": "No Excel, =PROCV(10;A2:C20;3;FALSO) retorna:", "opcoes": ["O valor da 3ª coluna da linha em que a 1ª coluna é exatamente 10", "A soma de todos os valores da 3ª coluna do intervalo maiores que 10", "O valor mais próximo de 10 em qualquer coluna", "A quantidade de linhas com o valor 10"], "explicacao": "FALSO exige correspondência exata na primeira coluna do intervalo."}, {"id": 11023, "materia": "rl", "nivel": 0, "enunciado": "Cada viatura leva 4 policiais. Para levar 28 policiais, são necessárias:", "opcoes": ["7 viaturas", "6 viaturas", "8 viaturas", "24 viaturas"], "explicacao": "28 ÷ 4 = 7."}, {"id": 11024, "materia": "rl", "nivel": 1, "enunciado": "Um mandado foi expedido numa segunda-feira e deve ser cumprido em até 4 dias. O último dia do prazo é:", "opcoes": ["Sexta-feira", "Quinta-feira", "Sábado", "Quarta-feira"], "explicacao": "Segunda + 4 dias = sexta-feira (contando terça, quarta, quinta e sexta)."}, {"id": 11025, "materia": "rl", "nivel": 2, "enunciado": "A negação de \"Algum preso fugiu\" é:", "opcoes": ["Nenhum preso fugiu", "Todos os presos fugiram", "Algum preso não fugiu", "Todo preso não ficou"], "explicacao": "A negação de \"algum\" é \"nenhum\"."}, {"id": 11026, "materia": "rl", "nivel": 2, "enunciado": "Uma viatura percorre 240 km com 20 litros de combustível. Para percorrer 360 km, ela precisa de:", "opcoes": ["30 litros", "25 litros", "36 litros", "40 litros"], "explicacao": "240 ÷ 20 = 12 km/L; 360 ÷ 12 = 30 litros."}, {"id": 11027, "materia": "rl", "nivel": 3, "enunciado": "Se \"Toda testemunha é maior de idade\" é verdadeira, então \"Alguma testemunha não é maior de idade\" é:", "opcoes": ["Falsa", "Verdadeira", "Indeterminada", "Equivalente"], "explicacao": "Uma é a negação da outra."}, {"id": 11028, "materia": "rl", "nivel": 4, "enunciado": "Numa gaveta há 4 coletes P e 6 coletes G. Tirando 2 sem olhar e sem devolver, a probabilidade de os dois serem G é:", "opcoes": ["1/3", "9/25", "3/5", "1/2"], "explicacao": "6/10 × 5/9 = 30/90 = 1/3."}, {"id": 11029, "materia": "dh", "nivel": 0, "enunciado": "O dia 10 de dezembro é o Dia Internacional dos:", "opcoes": ["Direitos Humanos", "Trabalhadores", "Povos Indígenas", "Refugiados"], "explicacao": "Data da adoção da Declaração Universal, em 1948."}, {"id": 11030, "materia": "dh", "nivel": 1, "enunciado": "A Constituição prevê a concessão de asilo político como um princípio das relações internacionais do Brasil?", "opcoes": ["Sim", "Não", "Só em guerra", "Só para europeus"], "explicacao": "Art. 4º, X, da Constituição."}, {"id": 11031, "materia": "dh", "nivel": 2, "enunciado": "A Convenção Interamericana para Prevenir e Punir a Tortura foi elaborada no âmbito da:", "opcoes": ["OEA", "OTAN", "União Europeia", "Mercosul"], "explicacao": "É um tratado do sistema interamericano (1985)."}, {"id": 11032, "materia": "dh", "nivel": 3, "enunciado": "A Convenção da ONU sobre a Eliminação de Todas as Formas de Discriminação contra a Mulher é conhecida pela sigla:", "opcoes": ["CEDAW", "UNICEF", "OMS", "FAO"], "explicacao": "Convenção adotada em 1979 e ratificada pelo Brasil."}, {"id": 11033, "materia": "dh", "nivel": 4, "enunciado": "O controle de convencionalidade consiste em verificar se as leis internas são compatíveis com:", "opcoes": ["Os tratados de direitos humanos", "As leis municipais", "Os regimentos internos dos tribunais", "As portarias dos ministérios"], "explicacao": "Juízes e a Administração devem aplicar os tratados de direitos humanos ratificados."}, {"id": 11034, "materia": "ml", "nivel": 0, "enunciado": "A sigla IML significa:", "opcoes": ["Instituto Médico Legal", "Instituto Militar de Lei", "Inspeção Médica Local", "Instituto de Medicina Laboral"], "explicacao": "É onde se fazem necropsias e exames de corpo de delito."}, {"id": 11035, "materia": "ml", "nivel": 1, "enunciado": "Um furador de gelo, que só perfura sem cortar, é um instrumento:", "opcoes": ["Perfurante", "Cortante", "Contundente", "Cortocontundente"], "explicacao": "Instrumento perfurante age pela ponta."}, {"id": 11036, "materia": "ml", "nivel": 2, "enunciado": "A coloração azulada ou arroxeada da pele e das unhas pela falta de oxigênio no sangue chama-se:", "opcoes": ["Cianose", "Icterícia", "Palidez", "Livor"], "explicacao": "É sinal comum nas asfixias."}, {"id": 11037, "materia": "ml", "nivel": 3, "enunciado": "Na morte por raio, a lesão típica na pele, com desenho parecido com galhos de árvore, chama-se:", "opcoes": ["Figura de Lichtenberg", "Marca de Jellinek", "Sinal de Benassi", "Mancha de Tardieu"], "explicacao": "As figuras (arborizações) de Lichtenberg são típicas da fulminação."}, {"id": 11038, "materia": "ml", "nivel": 4, "enunciado": "A marca elétrica de Jellinek, no ponto de entrada da corrente, é típica da:", "opcoes": ["Eletroplessão", "Fulminação", "Carbonização por fogo", "Queimadura química"], "explicacao": "Eletroplessão é a lesão por eletricidade artificial (industrial); fulminação é por eletricidade natural (raio)."}, {"id": 11039, "materia": "est", "nivel": 1, "enunciado": "Nos números 4, 8, 8 e 10, a moda é:", "opcoes": ["8", "4", "10", "7,5"], "explicacao": "Moda é o valor que mais aparece."}, {"id": 11040, "materia": "est", "nivel": 3, "enunciado": "O tempo de atendimento numa delegacia tem desvio padrão de 5 minutos. A variância é:", "opcoes": ["25", "5", "10", "2,24"], "explicacao": "A variância é o quadrado do desvio padrão: 5² = 25 (minutos ao quadrado)."}, {"id": 11041, "materia": "est", "nivel": 4, "enunciado": "As notas de uma turma tinham média 6. O professor dobrou todas as notas. A nova média é:", "opcoes": ["12", "6", "8", "36"], "explicacao": "Multiplicar todos os valores por uma constante multiplica a média pela mesma constante."}, {"id": 11042, "materia": "cont", "nivel": 1, "enunciado": "Uma receita de serviços prestados, recebida à vista, aumenta o:", "opcoes": ["Patrimônio líquido", "Passivo", "Capital social", "Imobilizado"], "explicacao": "Receitas aumentam o resultado e, assim, o PL."}, {"id": 11043, "materia": "cont", "nivel": 2, "enunciado": "O pagamento dos salários do mês dos funcionários é registrado como:", "opcoes": ["Despesa", "Receita", "Ativo", "Capital social"], "explicacao": "Salários consumidos no período são despesa."}, {"id": 11044, "materia": "cont", "nivel": 4, "enunciado": "A compra de um veículo a prazo, para uso da empresa, é fato contábil:", "opcoes": ["Permutativo", "Modificativo aumentativo", "Modificativo diminutivo", "Misto"], "explicacao": "Entra um bem no ativo e surge uma dívida no passivo, sem alterar o PL."}, {"id": 11045, "materia": "igual", "nivel": 3, "enunciado": "Pela Lei 7.716/1989, quando o racismo é praticado em contexto de \"brincadeira\" ou recreação, a pena:", "opcoes": ["Aumenta de 1/3 até a metade", "Diminui pela metade, por ser brincadeira", "Deixa de existir", "Vira só multa"], "explicacao": "Art. 20-A da Lei 7.716/1989 (racismo recreativo, incluído pela Lei 14.532/2023)."}, {"id": 11046, "materia": "pcd", "nivel": 0, "enunciado": "A vaga de estacionamento com o símbolo de pessoa com deficiência é reservada a:", "opcoes": ["Veículos com pessoa com deficiência e credencial", "Qualquer carro por até 5 minutos", "Carros de entrega", "Táxis e motoristas de aplicativo"], "explicacao": "Art. 47 da Lei 13.146/2015: a vaga exige a credencial do veículo."}]$q$::jsonb)
  as x(id integer, materia text, nivel smallint, enunciado text, opcoes jsonb, explicacao text)
on conflict (id) do update set materia = excluded.materia, nivel = excluded.nivel, enunciado = excluded.enunciado, opcoes = excluded.opcoes, explicacao = excluded.explicacao;

select setval(pg_get_serial_sequence('public.questoes', 'id'), (select max(id) from public.questoes where id < 1000000));
select nivel, count(*) as questoes_novas from public.questoes where id between 10947 and 11046 group by nivel order by nivel;
select public.questoes_versao() as nova_versao;
